"use client";
import { Suspense, useEffect, useState } from "react";


import { useSearchParams } from "next/navigation";
import Link from "next/link";
import { api } from "@/lib/api";
import { formatMoney } from "@/lib/money";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Spinner } from "@/components/ui/spinner";
import { useCart } from "@/lib/cart-context";

interface OrderDetail {
  id: string;
  number: number;
  status: string;
  payment: string;
  totalCents: number;
  currency: string;
  itemCount: number;
  lines: Array<{
    title: string;
    variantName: string | null;
    quantity: number;
    unitPriceCents: number;
  }>;
}

function SuccessContent() {
  const searchParams = useSearchParams();
  const { clear, reconcile } = useCart();

  useEffect(() => {
    void clear();
    void reconcile();
  }, []);

  useEffect(() => {
    const guestToken = sessionStorage.getItem("guestToken");
    if (guestToken) {
      sessionStorage.removeItem("guestToken");
    }
  }, []);

  return (
    <div className="mx-auto max-w-2xl p-6">
      <Card>
        <CardHeader>
          <CardTitle>Payment successful</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6 text-center">
          <div className="space-y-2">
            <h2 className="text-2xl font-semibold">Thank you!</h2>
            <p className="text-muted-foreground">
              Your order has been received. Check your email for confirmation.
            </p>
          </div>
          <Button asChild>
            <Link href="/marketplace">Continue shopping</Link>
          </Button>
          <Button variant="outline" asChild>
            <Link href="/profile/orders">View my orders</Link>
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}

export default function CheckoutSuccessPage() {
  return (
    <Suspense fallback={<div className="flex min-h-[60vh] items-center justify-center"><Spinner className="size-6" /></div>}>
      <SuccessContent />
    </Suspense>
  );
}
